/**
 * Generates CSS from design/tokens.json (the Figma variable export).
 *
 *   src/styles/tokens.css : CSS variables. Primitives, semantic Light (:root)
 *                           and Dark ([data-theme="dark"] + prefers-color-scheme).
 *   src/styles/theme.css  : Tailwind v4 @theme mapping so utilities read like
 *                           the tokens (bg-page, text-primary, border-subtle…),
 *                           plus one `type-*` utility per text style.
 *
 * Never edit the generated files by hand. Edit tokens.json and re-run
 * `npm run tokens` (also runs on predev / prebuild).
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const tokens = JSON.parse(readFileSync(join(root, 'design/tokens.json'), 'utf8')) as Tokens

interface TextStyle {
  font: string
  weight: number
  italic?: boolean
  size: number
  lineHeight: string
  letterSpacing: string
  textTransform?: string
}
interface Tokens {
  primitives: Record<string, string>
  semantic: Record<string, { light: string; dark: string }>
  spacing: Record<string, number>
  radius: Record<string, number>
  textStyles: Record<string, TextStyle>
}

const cssVar = (name: string) => `--${name.replaceAll('/', '-')}`
const ref = (name: string) => `var(${cssVar(name)})`
const banner = `/* GENERATED by scripts/build-tokens.ts from design/tokens.json. Do not edit. */\n`

// ---------- tokens.css ----------
const primitiveLines = Object.entries(tokens.primitives).map(([name, value]) => {
  const alias = value.match(/^\{(.+)\}$/)
  return `  ${cssVar(name)}: ${alias ? ref(alias[1]) : value};`
})
const mode = (m: 'light' | 'dark', indent = '  ') =>
  Object.entries(tokens.semantic)
    .map(([name, v]) => `${indent}${cssVar(name)}: ${ref(v[m])};`)
    .join('\n')
const spacingLines = Object.entries(tokens.spacing).map(([n, v]) => `  ${cssVar(n)}: ${v}px;`)
const radiusLines = Object.entries(tokens.radius).map(([n, v]) => `  ${cssVar(n)}: ${v}px;`)

const tokensCss = `${banner}
:root {
  /* Primitives */
${primitiveLines.join('\n')}

  /* Spacing */
${spacingLines.join('\n')}

  /* Radius */
${radiusLines.join('\n')}

  /* Semantic · Light */
  color-scheme: light;
${mode('light')}
}

/* Semantic · Dark (system preference, unless the user forced light) */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    color-scheme: dark;
${mode('dark', '    ')}
  }
}

/* Semantic · Dark (forced) */
:root[data-theme='dark'] {
  color-scheme: dark;
${mode('dark')}
}
`

// ---------- theme.css ----------
// Semantic token → Tailwind theme variable(s). Tailwind v4 resolves
// bg-* from --background-color-*, text-* from --text-color-*, etc.
function themeKeys(name: string): string[] {
  const [group, ...rest] = name.split('/')
  const key = rest.join('-')
  switch (group) {
    case 'background':
      return [`--background-color-${key}`]
    case 'text':
      return [`--text-color-${key}`]
    case 'border':
      return [`--border-color-${key}`]
    case 'action':
      if (key.startsWith('link')) return [`--text-color-${key}`]
      if (key === 'focus') return ['--outline-color-focus', '--border-color-focus']
      return [`--background-color-action-${key}`]
    case 'feedback': {
      const [status, kind] = rest
      if (kind === 'solid') return [`--background-color-${status}`, `--border-color-${status}`]
      if (kind === 'subtle') return [`--background-color-${status}-subtle`]
      return [`--text-color-${status}`]
    }
  }
  throw new Error(`Unmapped semantic token ${name}`)
}

const colorTheme = Object.keys(tokens.semantic)
  .flatMap((name) => themeKeys(name).map((k) => `  ${k}: ${ref(name)};`))
  .join('\n')
const spacingTheme = Object.entries(tokens.spacing)
  .map(([n]) => `  --spacing-${n.split('/')[1]}: ${ref(n)};`)
  .join('\n')
const radiusTheme = Object.entries(tokens.radius)
  .map(([n]) => `  --radius-${n.split('/')[1]}: ${ref(n)};`)
  .join('\n')

const fontVar: Record<string, string> = {
  'Cormorant Garamond': '--font-serif',
  'Gothic A1': '--font-sans',
  'Instrument Serif': '--font-numeral',
}
const utilName: Record<string, string> = {
  H1: 'type-h1',
  H2: 'type-h2',
  Description: 'type-description',
  H3: 'type-h3',
  H4: 'type-h4',
  'Text - Label': 'type-label',
  'Text - Body': 'type-body',
  'Text - Body Bold': 'type-body-bold',
  Caps: 'type-caps',
  'Button - Serif': 'type-button-serif',
  Numeral: 'type-numeral',
  'Numeral S': 'type-numeral-s',
}
const typeUtilities = Object.entries(tokens.textStyles)
  .map(([name, s]) => {
    const util = utilName[name]
    if (!util) throw new Error(`No utility name for text style "${name}"`)
    return `/* ${name} */
@utility ${util} {
  font-family: var(${fontVar[s.font]});
  font-weight: ${s.weight};
  font-style: ${s.italic ? 'italic' : 'normal'};
  font-size: ${s.size}px;
  line-height: ${s.lineHeight};
  letter-spacing: ${s.letterSpacing === '0' ? '0' : s.letterSpacing};
  text-transform: ${s.textTransform ?? 'none'};
}`
  })
  .join('\n\n')

const themeCss = `${banner}
@theme inline {
  /* Reset Tailwind defaults so only Eight Days tokens exist */
  --color-*: initial;
  --spacing-*: initial;
  --radius-*: initial;
  --font-*: initial;

  --color-transparent: transparent;
  --color-current: currentColor;

  /* Fonts */
  --font-serif: 'Cormorant Garamond', 'Times New Roman', serif;
  --font-sans: 'Gothic A1', system-ui, sans-serif;
  --font-numeral: 'Instrument Serif', 'Times New Roman', serif;

  /* Breakpoints: 375 → 768 → 1024 → 1440 */
  --breakpoint-sm: 480px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --breakpoint-xl: 1280px;
  --breakpoint-2xl: 1440px;

  /* Semantic colors */
${colorTheme}

  /* Spacing (px-named: p-16 = 16px). 0 is not a token but keeps inset-0, m-0 etc. */
  --spacing-0: 0px;
${spacingTheme}

  /* Radius (square by default) */
  --radius: 0px;
${radiusTheme}
}

${typeUtilities}
`

writeFileSync(join(root, 'src/styles/tokens.css'), tokensCss)
writeFileSync(join(root, 'src/styles/theme.css'), themeCss)
console.log(
  `tokens: ${Object.keys(tokens.primitives).length} primitives, ${Object.keys(tokens.semantic).length} semantic, ${Object.keys(tokens.textStyles).length} text styles → src/styles/{tokens,theme}.css`,
)
